function mockEmployee(employeeId: string): Employee {
  const found = MOCK_EMPLOYEES.find((e) => e.id === employeeId);
  if (!found) throw new BambooError('Not found in BambooHR.', 404);
  return { ...found };
}

export const __mockRoster = MOCK_EMPLOYEES;
